import random
from itertools import combinations

def has_short_cycle(adj, n, max_len=6):
    # BFS from each vertex to detect cycles of length <= max_len
    for s in range(n):
        # BFS, tracking parent; if we find a neighbor already visited at appropriate distance -> cycle
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        queue = [s]
        while queue:
            newq = []
            for u in queue:
                if dist[u] >= max_len:
                    continue
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        newq.append(v)
                    elif v != parent[u]:
                        # found cycle of length dist[u]+dist[v]+1
                        if dist[u]+dist[v]+1 <= max_len:
                            return True
            queue = newq
    return False

def girth_at_least_7(edges, n):
    adj = [set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    return not has_short_cycle(adj, n, 6)

