import random
from collections import deque
from itertools import combinations

n = 17

def dist_uv(adj, u, v, limit):
    if u == v: return 0
    dist = {u:0}
    q = deque([u])
    while q:
        x = q.popleft()
        if dist[x] >= limit: continue
        for y in adj[x]:
            if y not in dist:
                dist[y] = dist[x]+1
                if y == v:
                    return dist[y]
                q.append(y)
    return limit+1

def run(seed, iters=500):
    random.seed(seed)
    all_edges = list(combinations(range(n), 2))
    adj = [set() for _ in range(n)]
    edges = set()
    random.shuffle(all_edges)
    for u,v in all_edges:
        if dist_uv(adj, u, v, 5) <= 5: continue
        edges.add((u,v))
        adj[u].add(v); adj[v].add(u)
    best = len(edges); best_e = set(edges)
    for it in range(iters):
        if len(edges) >= 27: return edges
        k = random.randint(1, 3)
        removed = random.sample(list(edges), min(k, len(edges)))
        for e in removed:
            edges.remove(e); adj[e[0]].discard(e[1]); adj[e[1]].discard(e[0])
        random.shuffle(all_edges)
        for u,v in all_edges:
            if (u,v) in edges: continue
            if dist_uv(adj, u, v, 5) <= 5: continue
            edges.add((u,v)); adj[u].add(v); adj[v].add(u)
        if len(edges) > best:
            best = len(edges); best_e = set(edges)
    return best_e

best_overall = 0; best_result = None
for seed in range(30):
    r = run(seed, 300)
    if len(r) > best_overall:
        best_overall = len(r); best_result = r
